static inline void dl_LTdokumentaciyau2ePrimer_give(dl_LTdokumentaciyau2ePrimer *l) { if (l) dan_hdr_give(&l->h, dl_LTdokumentaciyau2ePrimer_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_LTdokumentaciyau2ePrimer *dl_LTdokumentaciyau2ePrimer_mut(dl_LTdokumentaciyau2ePrimer **pp) {
    dl_LTdokumentaciyau2ePrimer *l = *pp;
    if (l->h.rc > 1) {
        dl_LTdokumentaciyau2ePrimer *r = dl_LTdokumentaciyau2ePrimer_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_LTdokumentaciyau2ePrimer *dl_LTdokumentaciyau2ePrimer_reversed(const dl_LTdokumentaciyau2ePrimer *l) {
    dl_LTdokumentaciyau2ePrimer *r = dl_LTdokumentaciyau2ePrimer_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { dt_dokumentaciyau2ePrimer t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_LTdokumentaciyau2ePrimer *dl_LTdokumentaciyau2ePrimer_slice(const dl_LTdokumentaciyau2ePrimer *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_LTdokumentaciyau2ePrimer_from(b - a + 1, l->items + a);
}

static dan_str dl_LTdokumentaciyau2ePrimer_str(const dl_LTdokumentaciyau2ePrimer *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dt_dokumentaciyau2ePrimer_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_LTdokumentaciyau2ePrimer_find(const dl_LTdokumentaciyau2ePrimer *l, dt_dokumentaciyau2ePrimer b) {
    for (int64_t i = 0; i < l->len; i++) { dt_dokumentaciyau2ePrimer a = l->items[i]; if (dt_dokumentaciyau2ePrimer_eq(a, b)) return i; }
    return -1;
}
static bool dl_LTdokumentaciyau2ePrimer_contains(const dl_LTdokumentaciyau2ePrimer *l, dt_dokumentaciyau2ePrimer b) { return dl_LTdokumentaciyau2ePrimer_find(l, b) >= 0; }
static bool dl_LTdokumentaciyau2ePrimer_eq(const dl_LTdokumentaciyau2ePrimer *x, const dl_LTdokumentaciyau2ePrimer *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { dt_dokumentaciyau2ePrimer a = x->items[i]; dt_dokumentaciyau2ePrimer b = y->items[i]; if (!(dt_dokumentaciyau2ePrimer_eq(a, b))) return false; }
    return true;
}


