/* ---- list [{стр: стр}] ---- */
/* h.rc - число мест (переменных, полей, элементов), где хранится список.
   Список - значение: если мест несколько, перед изменением делается копия.
   Список сам учитывает свои элементы: при добавлении элемент получает ещё
   одно место хранения, при удалении - теряет его. */
struct dl_LDss { dan_hdr h; int64_t len, cap; dm_Dss* *items; };

static void dl_LDss_destroy(dan_hdr *h) {
    dl_LDss *l = (dl_LDss *)(void *)h;
    for (int64_t i = 0; i < l->len; i++) dm_Dss_release(l->items[i]);
    dan_free(l->items);
    dan_free(l);
}

static dl_LDss *dl_LDss_from(int64_t n, dm_Dss* const *src) {
    dl_LDss *l = dan_alloc(sizeof *l);
    dan_hdr_new(&l->h, dl_LDss_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(dm_Dss*));
    for (int64_t i = 0; i < n; i++) l->items[i] = dm_Dss_share(src[i]);
    return l;
}

static void dl_LDss_push(dl_LDss *l, dm_Dss* v) {
    if (l->len == l->cap) {
        l->cap *= 2;
        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof(dm_Dss*));
    }
    l->items[l->len++] = dm_Dss_share(v);
}

static dm_Dss* dl_LDss_get(const dl_LDss *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return l->items[i];
}

static dm_Dss* *dl_LDss_at(dl_LDss *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return &l->items[i];
}

static void dl_LDss_set(dl_LDss *l, int64_t i, dm_Dss* v, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dm_Dss* old = l->items[i];
    l->items[i] = dm_Dss_share(v);
    dm_Dss_release(old);
    (void)old;
}

static void dl_LDss_write(const dl_LDss *l) {
    putchar('[');
    for (int64_t i = 0; i < l->len; i++) {
        if (i) fputs(", ", stdout);
        dm_Dss_write(l->items[i]);
    }
    putchar(']');
}

static void dl_LDss_insert(dl_LDss *l, int64_t i, dm_Dss* v, int line) {
    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);
    dl_LDss_push(l, v);
    dm_Dss* last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(dm_Dss*));
    l->items[i] = last;
}

static void dl_LDss_remove(dl_LDss *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    dm_Dss* old = l->items[i];
    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof(dm_Dss*));
    l->len--;
    dm_Dss_release(old);
    (void)old;
}

/* новый список с теми же элементами; элементы получают ещё одно место хранения */
static dl_LDss *dl_LDss_copy(const dl_LDss *l) {
    return dl_LDss_from(l->len, l->items);
}

static inline dl_LDss *dl_LDss_share(dl_LDss *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_LDss_release(dl_LDss *l) { if (l) dan_hdr_release(&l->h, dl_LDss_destroy); }
static inline void dl_LDss_give(dl_LDss *l) { if (l) dan_hdr_give(&l->h, dl_LDss_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_LDss *dl_LDss_mut(dl_LDss **pp) {
    dl_LDss *l = *pp;
    if (l->h.rc > 1) {
        dl_LDss *r = dl_LDss_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_LDss *dl_LDss_reversed(const dl_LDss *l) {
    dl_LDss *r = dl_LDss_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { dm_Dss* t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_LDss *dl_LDss_slice(const dl_LDss *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_LDss_from(b - a + 1, l->items + a);
}

static dan_str dl_LDss_str(const dl_LDss *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dm_Dss_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_LDss_find(const dl_LDss *l, dm_Dss* b) {
    for (int64_t i = 0; i < l->len; i++) { dm_Dss* a = l->items[i]; if (dm_Dss_eq(a, b)) return i; }
    return -1;
}
static bool dl_LDss_contains(const dl_LDss *l, dm_Dss* b) { return dl_LDss_find(l, b) >= 0; }
static bool dl_LDss_eq(const dl_LDss *x, const dl_LDss *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { dm_Dss* a = x->items[i]; dm_Dss* b = y->items[i]; if (!(dm_Dss_eq(a, b))) return false; }
    return true;
}


